    [6667]={name="Engineer's Cloak",quality=2,ilvl=27,sourceType="quest_reward",instructions="Reward from the quest 'Gerenzo Wrenchwhistle' - pick it over the other choices. In Stonetalon Mountains.",zone="Stonetalon Mountains",questName="Gerenzo Wrenchwhistle",lore="I met Gerenzo once, but let me tell you, he's not easy on the eyes. His flesh looks like it's rotting away, and he's grafted metal and gears onto his body, replaced some of his limbs with mechanical ones."},
    [6744]={name="Gloves of Kapelan",quality=2,ilvl=33,sourceType="quest_reward",instructions="Reward from the quest 'Alliance Relations' - pick it over the other choices. In Orgrimmar.",zone="Orgrimmar",questName="Alliance Relations",lore="The fight goes well. Perhaps the Warchief will allow us to return to our homes before the seasons change if we continue to make such great strides in our battle against the demons and their underlings."},
