    [7334]={name="Efflorescent Robe",quality=2,ilvl=28,sourceType="quest_reward",instructions="Reward from the quest 'Reception from Tyrande' - pick it over the other choices. In Stonetalon Mountains.",zone="Stonetalon Mountains",questName="Reception from Tyrande",lore="I am sure Tyrande Whisperwind herself would like to thank you for taking part in this mission. It may not appear so on the surface, but what you've helped start could very well strengthen our foothold in the Stonetalon Mountains."},
