    [9513]={name="Ley Staff",quality=2,ilvl=13,sourceType="quest_reward",instructions="Reward from the quest 'Mirror Lake' - pick it over the other choices.",questName="Mirror Lake",lore="This world has been victim to massive mystic struggles, which tore magic currents from once stable channels. We struggle to determine the effects these changes have caused, and some of us fear the worst!"},
