    [10637]={name="Brewer's Gloves",quality=2,ilvl=15,sourceType="quest_reward",instructions="Reward from the quest 'Sample for Helbrim' - pick it over the other choices. In Undercity.",zone="Undercity",questName="Sample for Helbrim",lore="A colleague in Kalimdor, Apothecary Helbrim, is researching the effects of Lordaeron toxins on the beasts of Kalimdor. He would be very interested in a sample of the wolf hearts Renferrel sent me."},
    [10654]={name="Jutebraid Gloves",quality=2,ilvl=31,sourceType="quest_reward",instructions="Reward from the quest 'Horde Presence' - pick it over the other choices. In The Barrens.",zone="The Barrens",questName="Horde Presence",lore="This scroll is from that scheming dryad Rynthariel, Keymaster of the Talon Den on Stonetalon Peak. She'll not be making any more contact with the messenger you looted this from, heh, but we must stand our ground here."},
    [10659]={name="Shard of the Splithooves",quality=2,ilvl=57,sourceType="quest_reward",instructions="Reward from the quest 'Heroes of Old'. In Blasted Lands.",zone="Blasted Lands",questName="Heroes of Old",lore="Please, take from this a relic of old. We no longer have a use for the item. May it serve you well in your fight against the legion."},
    [10708]={name="Skullspell Orb",quality=2,ilvl=52,sourceType="quest_reward",instructions="Reward from the quest 'Return to Tymor' - pick it over the other choices. In Ironforge.",zone="Ironforge",questName="Return to Tymor",lore="Tymor didn't give me anything to pay you with, so I suggest you take it up with him when you get back to Ironforge. I'm sure he'll still be in his place in the Mystic Ward."},
    [10742]={name="Dragonflight Leggings",quality=2,ilvl=51,sourceType="quest_reward",instructions="Reward from the quest 'Set Them Ablaze!' - pick it over the other choices. In Searing Gorge.",zone="Searing Gorge",questName="Set Them Ablaze!",lore="Listen well. While the four towers can never be destroyed, you can use the torch of retribution to set them ablaze for a very long period of time: A fire that no element or force can subdue."},
    [10787]={name="Atal'ai Gloves",quality=3,ilvl=52,reqLevel=47,sourceType="boss_drop",instructions="Drops from Zolo in Sunken Temple.",zone="Sunken Temple",npc="Zolo"},
    [10820]={name="Jackseed Belt",quality=2,ilvl=15,sourceType="quest_reward",instructions="Reward from the quest 'Mura Runetotem' - pick it over the other choices. In The Barrens.",zone="The Barrens",questName="Mura Runetotem",lore="My clanmate, Mura Runetotem, traveled to Silverpine so that she might aid our undead allies. Silverpine is an ailing forest, a dying forest, and it was Mura's hope to bring it new life."},
