    [16914]={name="Netherwind Crown",quality=4,ilvl=76,reqLevel=60,sourceType="boss_drop",instructions="Drops from Onyxia in Onyxia's Lair.",zone="Onyxia's Lair",npc="Onyxia",lore="Deathwing's daughter and Nefarian's sister. She spent years in Stormwind as Lady Katrana Prestor, advising the throne she was working to undermine."},
