    [21186]={name="Rockfury Bracers",quality=4,ilvl=62,sourceType="quest_reward",instructions="Reward from the quest 'Stalwart's Battlegear' - pick it over the other choices. In Silithus.",zone="Silithus",questName="Stalwart's Battlegear",lore="The badges you collect from performing combat, logistics and tactical assignments for Windcaller Proudhorn are more than just for show. You'd be wise to hold on to them."},
    [21318]={name="Earth Warder's Gloves",quality=2,ilvl=58,sourceType="quest_reward",instructions="Reward from the quest 'Winterfall Activity' - pick it over the other choices. In Timbermaw Hold.",zone="Timbermaw Hold",questName="Winterfall Activity",lore="The Timbermaw tend to stay to themselves. While we do allow safe passage to those we trust, we try to avoid other furbolg tribes if at all possible."},
    [21343]={name="Enigma Robes",quality=4,ilvl=88,reqLevel=60,sourceType="quest_reward",instructions="Reward from the quest 'Enigma Robes'. In Ahn'Qiraj.",zone="Ahn'Qiraj",questName="Enigma Robes",lore="The unmentionable Old God slowly awakens from his slumber beneath Ahn'Qiraj. The terrible fate that awaits Azeroth could come in days or years; time has no meaning for beings of his power."},
    [21344]={name="Enigma Boots",quality=4,ilvl=78,reqLevel=60,sourceType="quest_reward",instructions="Reward from the quest 'Enigma Boots'. In Ahn'Qiraj.",zone="Ahn'Qiraj",questName="Enigma Boots",lore="The most powerful qiraji wield items of such might, they'd give pause even to a dragon. Bring me the qiraji bindings of dominance and other minor components by and I'll create a set of powerful boots for you."},
    [21345]={name="Enigma Shoulderpads",quality=4,ilvl=78,reqLevel=60,sourceType="quest_reward",instructions="Reward from the quest 'Enigma Shoulderpads'. In Ahn'Qiraj.",zone="Ahn'Qiraj",questName="Enigma Shoulderpads",lore="It is said among us that the ornate shoulder armor worn by the mortal races started as an attempt to emulate the wings of a dragon."},
    [21346]={name="Enigma Leggings",quality=4,ilvl=81,reqLevel=60,sourceType="quest_reward",instructions="Reward from the quest 'Enigma Leggings'. In Ahn'Qiraj.",zone="Ahn'Qiraj",questName="Enigma Leggings",lore="Bring me a sample of his skin along with other minor components and I shall craft you leggings of great power."},
    [21347]={name="Enigma Circlet",quality=4,ilvl=81,reqLevel=60,sourceType="quest_reward",instructions="Reward from the quest 'Enigma Circlet'. In Ahn'Qiraj.",zone="Ahn'Qiraj",questName="Enigma Circlet",lore="The Twin Emperors... their incessant whispers are slowly taking a toll on my sanity. They mock me, knowing I cannot step further into their domain to save my brother Arygos."},
    [21565]={name="Rune of Perfection",quality=3,ilvl=45,reqLevel=40,sourceType="vendor",instructions="Bought from the Warsong Gulch quartermaster with marks of honor. Alliance: Illiyana Moonblaze at Silverwing Grove, Ashenvale. Horde: Kelm Hargunth at Mor'shan Base Camp, The Barrens."},
    [21566]={name="Rune of Perfection",quality=3,ilvl=25,reqLevel=20,sourceType="vendor",instructions="Bought from the Warsong Gulch quartermaster with marks of honor. Alliance: Illiyana Moonblaze at Silverwing Grove, Ashenvale. Horde: Kelm Hargunth at Mor'shan Base Camp, The Barrens."},
    [21567]={name="Rune of Duty",quality=3,ilvl=45,reqLevel=40,sourceType="vendor",instructions="Bought from the Warsong Gulch quartermaster with marks of honor. Alliance: Illiyana Moonblaze at Silverwing Grove, Ashenvale. Horde: Kelm Hargunth at Mor'shan Base Camp, The Barrens."},
    [21568]={name="Rune of Duty",quality=3,ilvl=25,reqLevel=20,sourceType="vendor",instructions="Bought from the Warsong Gulch quartermaster with marks of honor. Alliance: Illiyana Moonblaze at Silverwing Grove, Ashenvale. Horde: Kelm Hargunth at Mor'shan Base Camp, The Barrens."},
    [21585]={name="Dark Storm Gauntlets",quality=4,ilvl=88,reqLevel=60,sourceType="boss_drop",instructions="Drops from C'Thun in Temple of Ahn'Qiraj.",zone="Temple of Ahn'Qiraj",npc="C'Thun",lore="An Old God, buried under Ahn'Qiraj by the titans rather than killed. It has been whispering to the qiraji ever since, and the whole war exists because it never stopped."},
    [21597]={name="Royal Scepter of Vek'lor",quality=4,ilvl=81,reqLevel=60,sourceType="boss_drop",instructions="Drops from Emperor Vek'lor in Temple of Ahn'Qiraj.",zone="Temple of Ahn'Qiraj",npc="Emperor Vek'lor",lore="Twin emperor of the qiraji, and the one who inherited C'Thun's gift for magic instead of his brother's strength. Neither twin can be killed far from the other."},
    [21600]={name="Boots of Epiphany",quality=4,ilvl=81,reqLevel=60,sourceType="boss_drop",instructions="Drops from Emperor Vek'lor in Temple of Ahn'Qiraj.",zone="Temple of Ahn'Qiraj",npc="Emperor Vek'lor",lore="Twin emperor of the qiraji, and the one who inherited C'Thun's gift for magic instead of his brother's strength. Neither twin can be killed far from the other."},
    [21608]={name="Amulet of Vek'nilash",quality=4,ilvl=81,reqLevel=60,sourceType="boss_drop",instructions="Drops from Emperor Vek'nilash in Temple of Ahn'Qiraj.",zone="Temple of Ahn'Qiraj",npc="Emperor Vek'nilash",lore="Twin emperor of the qiraji, and the stronger arm of the pair. Kill one and the other heals him, so both must fall together."},
    [21611]={name="Burrower Bracers",quality=4,ilvl=81,reqLevel=60,sourceType="boss_drop",instructions="Drops from Ouro.",npc="Ouro",lore="A sandworm grown enormous under the desert, surfacing only to feed."},
    [21622]={name="Sharpened Silithid Femur",quality=4,ilvl=78,reqLevel=60,sourceType="boss_drop",instructions="Drops from Viscidus in Temple of Ahn'Qiraj.",zone="Temple of Ahn'Qiraj",npc="Viscidus",lore="A living mass of qiraji poison. It has to be frozen solid and then shattered, which is not how most things die."},
    [21686]={name="Mantle of Phrenic Power",quality=4,ilvl=76,reqLevel=60,sourceType="boss_drop",instructions="Drops from Princess Yauj in Temple of Ahn'Qiraj.",zone="Temple of Ahn'Qiraj",npc="Princess Yauj",lore="One of the qiraji triumvirate, who heals her fellow councillors and calls in broodlings when pressed."},
    [21709]={name="Ring of the Fallen God",quality=4,ilvl=88,reqLevel=60,sourceType="quest_reward",instructions="Reward from the quest 'The Savior of Kalimdor' - pick it over the other choices. In Ahn'Qiraj.",zone="Ahn'Qiraj",questName="The Savior of Kalimdor",lore="To the Caverns of Time you go, Lord:Lady;. Anachronos awaits your return. Give him the eye of C'Thun as he will undoubtedly wish to place it in his master's collection."},
    [22064]={name="Sorcerer's Boots",quality=4,ilvl=60,sourceType="quest_reward",instructions="Reward from the quest 'Anthion's Parting Words'. In Ironforge.",zone="Ironforge",questName="Anthion's Parting Words",lore="Valthalak's soul was stored in this amulet. In our greed we foolishly split it into three parts, not knowing the curse that would await us. The only way to stop Valthalak's spell is to put the medallion back together."},
    [22065]={name="Sorcerer's Crown",quality=4,ilvl=60,sourceType="quest_reward",instructions="Reward from the quest 'Saving the Best for Last'. In Ironforge.",zone="Ironforge",questName="Saving the Best for Last",lore="That's an amazing story! You have my thanks, and the heartfelt gratitude of all who were involved. Now maybe I'll be able to sleep at night with both eyes shut."},
    [22066]={name="Sorcerer's Gloves",quality=4,ilvl=55,sourceType="quest_reward",instructions="Reward from the quest 'Just Compensation'. In Ironforge.",zone="Ironforge",questName="Just Compensation",lore="I believe a reward is in order if I'm to keep you interested in saving my skin. Bring me an ordinary belt and a set of gloves that you wish to upgrade."},
    [22149]={name="Beads of Ogre Mojo",quality=3,ilvl=63,sourceType="quest_reward",instructions="Reward from the quest 'Falrin's Vendetta' - pick it over the other choices. In Dire Maul.",zone="Dire Maul",questName="Falrin's Vendetta",lore="Yet I'm not one to give out favors freely, even if you were sent here by an old friend. I hold nothing but hatred and contempt for our brutish ogre neighbors."},
    [22256]={name="Mana Shaping Handwraps",quality=3,ilvl=57,reqLevel=52,sourceType="world_drop",instructions="Drops from Watchman Doomgrip (rare elite).",npc="Watchman Doomgrip"},
