    [23001]={name="Eye of Diminution",quality=4,ilvl=85,reqLevel=60,sourceType="boss_drop",instructions="Drops from Thaddius in Naxxramas.",zone="Naxxramas",npc="Thaddius",lore="Two abominations sewn into one and animated with stolen lightning -- one of Kel'Thuzad's more ambitious experiments in the Construct Quarter.",proc="Use: Reduces the threat you generate by [35 - max(0, Level - 60)]% for 20 sec. (2 Min Cooldown)"},
    [23017]={name="Veil of Eclipse",quality=4,ilvl=83,reqLevel=60,sourceType="boss_drop",instructions="Drops from Instructor Razuvious in Naxxramas.",zone="Naxxramas",npc="Instructor Razuvious",lore="A death knight who trains the Scourge's new officers. He is too strong for his own students to touch, which is exactly the point of the lesson."},
